static const char *RES_HTML_NETWORK_DIAGNOSTICS_HTML = 
    "<div class=\"panel\"><div class=\"panel-header\">网络诊断</div><div class=\"panel-body\"><form method=\"post\" action=\"/network\" onsubmit=\"var btn=document.getElementById('network-ping-btn');if(btn){btn.disabled=true;btn.innerText='Ping中...';}\"><div class=\"form-group\"><label class=\"form-label\">目标 IP/域名</label><input class=\"form-input\" name=\"ping_target\" value=\"%s\"></div><div class=\"form-group\"><label class=\"form-label\"></label><button id=\"network-ping-btn\" type=\"submit\" class=\"btn\">Ping</button></div><div class=\"form-group\" style=\"align-items:flex-start;\"><label class=\"form-label\">测试结果</label><textarea class=\"form-input\" style=\"width:100%%;max-width:100%%;height:360px;white-space:pre;overflow:auto;font-family:monospace;\">%s</textarea></div></form></div></div><script>function toggleProto(val) {  var isDhcp = (val === 'dhcp');  document.getElementById('ip').disabled = isDhcp;  document.getElementById('mask').disabled = isDhcp;  document.getElementById('gateway').disabled = isDhcp;}toggleProto(document.getElementById('proto_select').value);</script>\n"
    "";

static const char *RES_HTML_NETWORK_INTERFACE_HTML = 
    "<div class=\"panel\">\n"
    "  <div class=\"panel-header\">接口配置 (eth0)</div>\n"
    "  <div class=\"panel-body\">\n"
    "    <div id=\"network-save-notice\" class=\"alert alert-success network-save-notice\" style=\"display:%s;\">网络已经修改，请在设备重启后使用新的IP访问，设备将在 <span id=\"network-reboot-countdown\">6</span> 秒后自动重启。</div>\n"
    "    <form method=\"post\" action=\"/network\">\n"
    "      <div class=\"form-group\">\n"
    "        <label class=\"form-label\">协议</label>\n"
    "        <select class=\"form-input\" id=\"proto_select\" name=\"proto\" onchange=\"toggleProto(this.value)\">\n"
    "          <option value=\"dhcp\" %s>DHCP (动态获取)</option>\n"
    "          <option value=\"static\" %s>Static (静态地址)</option>\n"
    "        </select>\n"
    "      </div>\n"
    "      <div id=\"static_fields\">\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">IP 地址</label>\n"
    "          <input class=\"form-input\" id=\"ip\" name=\"ip\" value=\"%s\">\n"
    "        </div>\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">子网掩码</label>\n"
    "          <input class=\"form-input\" id=\"mask\" name=\"mask\" value=\"%s\">\n"
    "        </div>\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">网关</label>\n"
    "          <input class=\"form-input\" id=\"gateway\" name=\"gateway\" value=\"%s\">\n"
    "        </div>\n"
    "      </div>\n"
    "      <div class=\"form-group\" style=\"margin-top:8px;\">\n"
    "        <label class=\"form-label\"></label>\n"
    "        <div style=\"flex:1;max-width:300px;display:flex;align-items:center;justify-content:space-between;\">\n"
    "          <button type=\"submit\" class=\"btn\">保存应用</button>\n"
    "          <button type=\"button\" class=\"btn\" onclick=\"openWifiDialog()\">WiFi配置</button>\n"
    "        </div>\n"
    "      </div>\n"
    "    </form>\n"
    "  </div>\n"
    "</div>\n"
    "<div id=\"wifi-dialog\" style=\"display:none;position:fixed;left:0;top:0;width:100%%;height:100%%;background:rgba(0,0,0,0.4);z-index:999;\">\n"
    "  <div style=\"width:520px;margin:80px auto;background:#fff;border-radius:4px;overflow:hidden;\">\n"
    "    <div class=\"panel-header\">WiFi 配置</div>\n"
    "    <div class=\"panel-body\">\n"
    "      <form method=\"post\" action=\"/network\">\n"
    "        <input type=\"hidden\" name=\"wifi_action\" value=\"save\">\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">WiFi 名称</label>\n"
    "          <input class=\"form-input\" name=\"wifi_ssid\" value=\"%s\" oninput=\"clearWifiMessage()\">\n"
    "        </div>\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">WiFi 密码</label>\n"
    "          <input class=\"form-input\" name=\"wifi_psk\" type=\"text\" value=\"%s\" oninput=\"clearWifiMessage()\">\n"
    "        </div>\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\">连接状态</label>\n"
    "          <input class=\"form-input\" value=\"%s\" readonly>\n"
    "        </div>\n"
    "        <div class=\"form-group\">\n"
    "          <label class=\"form-label\"></label>\n"
    "          <button type=\"submit\" class=\"btn\" style=\"height:40px;line-height:38px;border-radius:4px;font-size:14px;font-weight:500;display:inline-flex;align-items:center;justify-content:center;\">保存</button>\n"
    "          <button type=\"button\" class=\"btn\" style=\"margin-left:32px;height:40px;line-height:38px;border-radius:4px;font-size:14px;font-weight:500;background:#0099cc;border-color:#008fb3;color:#fff;display:inline-flex;align-items:center;justify-content:center;\" onclick=\"closeWifiDialog()\">关闭</button>\n"
    "        </div>\n"
    "        <div class=\"form-group\" id=\"wifi-message-group\" style=\"border-bottom:none;display:%s;\">\n"
    "          <div id=\"wifi-message\" class=\"alert %s\" style=\"width:100%%;margin:0;\">%s</div>\n"
    "        </div>\n"
    "      </form>\n"
    "    </div>\n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "function clearWifiMessage() {\n"
    "  var group = document.getElementById('wifi-message-group');\n"
    "  var msg = document.getElementById('wifi-message');\n"
    "  if (group) {\n"
    "    group.style.display = 'none';\n"
    "  }\n"
    "  if (msg) {\n"
    "    msg.className = 'alert';\n"
    "    msg.innerText = '';\n"
    "  }\n"
    "}\n"
    "function openWifiDialog(clearMessage) {\n"
    "  if (clearMessage !== false) {\n"
    "    clearWifiMessage();\n"
    "  }\n"
    "  document.getElementById('wifi-dialog').style.display = 'block';\n"
    "}\n"
    "function closeWifiDialog() {\n"
    "  document.getElementById('wifi-dialog').style.display = 'none';\n"
    "}\n"
    "if ('%s' === '1') {\n"
    "  openWifiDialog(false);\n"
    "}\n"
    "if ('%s' === 'block') {\n"
    "  (function(){\n"
    "    var countdownEl = document.getElementById('network-reboot-countdown');\n"
    "    var remain = 6;\n"
    "    if (!countdownEl) return;\n"
    "    countdownEl.innerText = String(remain);\n"
    "    var timer = setInterval(function(){\n"
    "      remain--;\n"
    "      if (remain <= 0) {\n"
    "        countdownEl.innerText = '0';\n"
    "        clearInterval(timer);\n"
    "        return;\n"
    "      }\n"
    "      countdownEl.innerText = String(remain);\n"
    "    }, 1000);\n"
    "  })();\n"
    "}\n"
    "</script>\n"
    "";

