    "        </div>\n"
    "      </div>\n"
    "      <div class=\"rf-result-note\" id=\"rf-scan-summary\">请输入频点范围后开始扫频。</div>\n"
    "      <div class=\"rf-chart-stats\" id=\"rf-chart-stats\" hidden>\n"
    "        <div class=\"rf-chart-stat\"><span>最低噪声</span><strong id=\"rf-chart-min\">--</strong></div>\n"
    "        <div class=\"rf-chart-stat\"><span>平均噪声</span><strong id=\"rf-chart-avg\">--</strong></div>\n"
    "        <div class=\"rf-chart-stat\"><span>最高噪声</span><strong id=\"rf-chart-max\">--</strong></div>\n"
    "      </div>\n"
    "      <div class=\"rf-chart-wrap\">\n"
    "        <div class=\"rf-chart-placeholder\" id=\"rf-scan-placeholder\">等待开始扫频</div>\n"
    "        <canvas id=\"rf-scan-chart\" class=\"rf-chart-canvas\"></canvas>\n"
    "      </div>\n"
    "    </div>\n"
    "  </div>\n"
    "\n"
    "  <div class=\"rf-card\">\n"
    "    <div class=\"rf-card-header\">ACM校准</div>\n"
    "    <div class=\"rf-card-body\">\n"
    "      <div class=\"rf-toolbar\">\n"
    "        <div class=\"rf-result-note\" id=\"rf-acm-summary\">点击按钮执行静态校准演示。</div>\n"
    "        <button type=\"button\" class=\"btn\" id=\"rf-acm-trigger\">开始校准</button>\n"
    "      </div>\n"
    "      <div class=\"rf-channel-grid\" id=\"rf-channel-grid\"></div>\n"
    "    </div>\n"
    "  </div>\n"
    "\n"
    "  <div class=\"rf-card\">\n"
    "    <div class=\"rf-card-header rf-card-header--split\">\n"
    "      <span>TurMass数据统计</span>\n"
    "      <button type=\"button\" class=\"btn rf-reset-btn\" id=\"rf-stats-reset\">清零</button>\n"
    "    </div>\n"
    "    <div class=\"rf-card-body\">\n"
    "      <div class=\"rf-stats-grid\">\n"
    "        <div class=\"rf-stat-box\">\n"
    "          <div class=\"rf-stat-title\">下行数据</div>\n"
    "          <div class=\"rf-stat-value\" id=\"rf-stat-downlink\">--</div>\n"
    "        </div>\n"
    "        <div class=\"rf-stat-box\">\n"
    "          <div class=\"rf-stat-title\">上行数据</div>\n"
    "          <div class=\"rf-stat-value\" id=\"rf-stat-uplink\">--</div>\n"
    "        </div>\n"
    "      </div>\n"
    "      <div class=\"rf-result-note\" id=\"rf-stats-summary\">从 /var/run/mqtt_stats.json 读取统计值。</div>\n"
    "    </div>\n"
    "  </div>\n"
    "</div>\n"
    "\n"
    "<script>\n"
    "(function(){\n"
    "  var scanPoints = [];\n"
    "  var acmChannels = [];\n"
    "  var statsTimerId = null;\n"
    "  var statsInFlight = false;\n"
    "  var stopped = false;\n"
    "  var lastStats = null;\n"
    "  var scanStatusTimerId = null;\n"
    "  var scanAnimationTimerId = null;\n"
    "  var scanBusy = false;\n"
    "  var scanAnimationStep = 0;\n"
    "  var acmStatusTimerId = null;\n"
    "  var acmAnimationTimerId = null;\n"
    "  var acmBusy = false;\n"
    "  var acmAnimationStep = 0;\n"
    "\n"
    "  function fetchJsonWithTimeout(url, options, timeoutMs) {\n"
    "    if (typeof AbortController === 'undefined') {\n"
    "      return fetch(url, options || {}).then(function(r){ return r.json(); });\n"
    "    }\n"
    "    var controller = new AbortController();\n"
    "    var timeoutId = setTimeout(function(){ controller.abort(); }, timeoutMs);\n"
    "    var opts = options || {};\n"
    "    opts.signal = controller.signal;\n"
    "    return fetch(url, opts).then(function(r){ return r.json(); }).finally(function(){\n"
    "      clearTimeout(timeoutId);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function setText(id, text) {\n"
    "    var el = document.getElementById(id);\n"
    "    if (el) el.innerText = text;\n"
    "  }\n"
    "\n"
    "  function setScanButtonBusy(busy) {\n"
    "    var button = document.getElementById('rf-scan-trigger');\n"
    "    scanBusy = busy;\n"
    "    if (!button) return;\n"
    "    button.disabled = busy;\n"
    "    if (busy) button.classList.add('rf-btn-disabled');\n"
    "    else button.classList.remove('rf-btn-disabled');\n"
    "  }\n"
    "\n"
    "  function showChartPlaceholder(text) {\n"
    "    var placeholder = document.getElementById('rf-scan-placeholder');\n"
    "    var canvas = document.getElementById('rf-scan-chart');\n"
    "    if (placeholder) {\n"
    "      placeholder.style.display = 'flex';\n"
    "      placeholder.innerText = text;\n"
    "    }\n"
    "    if (canvas) {\n"
    "      canvas.style.display = 'none';\n"
    "    }\n"
    "  }\n"
    "\n"
    "  function hideChartPlaceholder() {\n"
    "    var placeholder = document.getElementById('rf-scan-placeholder');\n"
    "    var canvas = document.getElementById('rf-scan-chart');\n"
    "    if (placeholder) placeholder.style.display = 'none';\n"
    "    if (canvas) canvas.style.display = 'block';\n"
    "  }\n"
    "\n"
    "  function normalizeFreqInput(value) {\n"
    "    if (value == null) return '';\n"
    "    var cleaned = String(value).replace(/\\s+/g, '').replace(/mhz/ig, 'M');\n"
    "    if (!cleaned) return '';\n"
    "    if (/m$/i.test(cleaned)) cleaned = cleaned.slice(0, -1);\n"
    "    var parsed = parseFloat(cleaned);\n"
    "    if (!isFinite(parsed)) return '';\n"
    "    return parsed.toFixed(1) + 'M';\n"
    "  }\n"
    "\n"
    "  function parseFreqValue(value) {\n"
    "    var normalized = normalizeFreqInput(value);\n"
    "    if (!normalized) return NaN;\n"
    "    return parseFloat(normalized);\n"
    "  }\n"
    "\n"
    "  function parseModeValue(value) {\n"
    "    var allowed = ['62.5k', '125k', '250k', '500k'];\n"
    "    if (value == null || value === '') return '';\n"
    "    var normalized = String(value).trim();\n"
    "    return allowed.indexOf(normalized) >= 0 ? normalized : '';\n"
    "  }\n"
    "\n"
    "  function drawScanChart() {\n"
    "    var canvas = document.getElementById('rf-scan-chart');\n"
    "    if (!canvas) return;\n"
    "    if (!scanPoints || !scanPoints.length) {\n"
    "      showChartPlaceholder('暂无扫频结果');\n"
    "      return;\n"
    "    }\n"
    "\n"
    "    hideChartPlaceholder();\n"
    "\n"
    "    var rect = canvas.getBoundingClientRect();\n"
    "    var width = Math.max(320, Math.round(rect.width || canvas.clientWidth || 720));\n"
    "    var height = Math.max(220, Math.round(rect.height || canvas.clientHeight || 260));\n"
    "    var dpr = window.devicePixelRatio || 1;\n"
    "    canvas.width = Math.max(1, Math.round(width * dpr));\n"
    "    canvas.height = Math.max(1, Math.round(height * dpr));\n"
    "    var ctx = canvas.getContext('2d');\n"
    "    if (!ctx) return;\n"
    "    if (ctx.setTransform) ctx.setTransform(1, 0, 0, 1, 0, 0);\n"
    "    ctx.scale(dpr, dpr);\n"
    "\n"
    "    ctx.clearRect(0, 0, width, height);\n"
    "\n"
    "    var values = [];\n"
    "    for (var valueIndex = 0; valueIndex < scanPoints.length; valueIndex++) {\n"
    "      var value = Number(scanPoints[valueIndex].rssi);\n"
    "      if (isFinite(value)) values.push(value);\n"
    "    }\n"
    "    if (!values.length) {\n"
    "      showChartPlaceholder('扫频结果中没有有效噪声值');\n"
    "      return;\n"
    "    }\n"
    "\n"
    "    var rawMin = Math.min.apply(null, values);\n"
    "    var rawMax = Math.max.apply(null, values);\n"
    "    var range = rawMax - rawMin;\n"
    "    var scalePadding = Math.max(2, range * 0.15);\n"
    "    if (range < 1) scalePadding = 5;\n"
    "    var yMin = Math.floor((rawMin - scalePadding) / 5) * 5;\n"
    "    var yMax = Math.ceil((rawMax + scalePadding) / 5) * 5;\n"
    "    if (yMax <= yMin) yMax = yMin + 10;\n"
    "\n"
    "    var paddingLeft = width < 520 ? 46 : 58;\n"
    "    var paddingRight = width < 520 ? 12 : 24;\n"
    "    var paddingTop = 20;\n"
    "    var paddingBottom = 42;\n"
    "    var chartWidth = width - paddingLeft - paddingRight;\n"
    "    var chartHeight = height - paddingTop - paddingBottom;\n"
    "\n"
    "    for (var i = 0; i <= 5; i++) {\n"
    "      var ratio = i / 5;\n"
    "      var y = paddingTop + chartHeight * ratio;\n"
    "      ctx.beginPath();\n"
    "      ctx.strokeStyle = i === 5 ? '#cbd9e8' : '#e7eef7';\n"
    "      ctx.lineWidth = 1;\n"
    "      ctx.moveTo(paddingLeft, y);\n"
    "      ctx.lineTo(width - paddingRight, y);\n"
    "      ctx.stroke();\n"
    "\n"
    "      ctx.fillStyle = '#70839a';\n"
    "      ctx.font = '12px sans-serif';\n"
    "      ctx.textAlign = 'right';\n"
    "      ctx.textBaseline = 'middle';\n"
    "      ctx.fillText((yMax - (yMax - yMin) * ratio).toFixed(0), paddingLeft - 9, y);\n"
    "    }\n"
    "\n"
    "    ctx.save();\n"
    "    ctx.translate(13, paddingTop + chartHeight / 2);\n"
    "    ctx.rotate(-Math.PI / 2);\n"
    "    ctx.fillStyle = '#70839a';\n"
    "    ctx.font = '12px sans-serif';\n"
    "    ctx.textAlign = 'center';\n"
    "    ctx.textBaseline = 'top';\n"
    "    ctx.fillText('噪声 (dBm)', 0, 0);\n"
    "    ctx.restore();\n"
    "\n"
    "    var pointX = function(index) {\n"
    "      return paddingLeft + (scanPoints.length === 1 ? chartWidth / 2 : chartWidth * index / (scanPoints.length - 1));\n"
    "    };\n"
    "    var pointY = function(rssi) {\n"
    "      return paddingTop + (yMax - Number(rssi)) / (yMax - yMin) * chartHeight;\n"
    "    };\n"
    "\n"
    "    var tickCount = Math.max(2, Math.min(9, Math.floor(chartWidth / 115) + 1));\n"
    "    var usedTicks = {};\n"
    "    ctx.fillStyle = '#52677f';\n"
    "    ctx.font = '12px sans-serif';\n"
    "    ctx.textAlign = 'center';\n"
    "    ctx.textBaseline = 'top';\n"
    "    for (var tick = 0; tick < tickCount; tick++) {\n"
    "      var tickIndex = Math.round(tick * (scanPoints.length - 1) / (tickCount - 1));\n"
    "      if (usedTicks[tickIndex]) continue;\n"
    "      usedTicks[tickIndex] = true;\n"
    "      var tickX = pointX(tickIndex);\n"
    "      ctx.beginPath();\n"
    "      ctx.strokeStyle = '#cbd9e8';\n"
    "      ctx.moveTo(tickX, paddingTop + chartHeight);\n"
    "      ctx.lineTo(tickX, paddingTop + chartHeight + 5);\n"
    "      ctx.stroke();\n"
    "      ctx.fillText(scanPoints[tickIndex].freq, tickX, paddingTop + chartHeight + 10);\n"
    "    }\n"
    "\n"
    "    var gradient = ctx.createLinearGradient(0, paddingTop, 0, paddingTop + chartHeight);\n"
    "    gradient.addColorStop(0, 'rgba(43, 114, 205, 0.28)');\n"
    "    gradient.addColorStop(1, 'rgba(43, 114, 205, 0.03)');\n"
    "    ctx.beginPath();\n"
    "    ctx.moveTo(pointX(0), paddingTop + chartHeight);\n"
    "    for (var j = 0; j < scanPoints.length; j++) ctx.lineTo(pointX(j), pointY(scanPoints[j].rssi));\n"
    "    ctx.lineTo(pointX(scanPoints.length - 1), paddingTop + chartHeight);\n"
    "    ctx.closePath();\n"
    "    ctx.fillStyle = gradient;\n"
    "    ctx.fill();\n"
    "\n"
    "    ctx.beginPath();\n"
    "    for (var lineIndex = 0; lineIndex < scanPoints.length; lineIndex++) {\n"
    "      var lineX = pointX(lineIndex);\n"
    "      var lineY = pointY(scanPoints[lineIndex].rssi);\n"
    "      if (lineIndex === 0) ctx.moveTo(lineX, lineY);\n"
    "      else ctx.lineTo(lineX, lineY);\n"
    "    }\n"
    "    ctx.strokeStyle = '#2b72cd';\n"
    "    ctx.lineWidth = 2;\n"
    "    ctx.lineJoin = 'round';\n"
    "    ctx.lineCap = 'round';\n"
    "    ctx.stroke();\n"
    "\n"
    "    if (scanPoints.length <= 20) {\n"
    "      ctx.fillStyle = '#ffffff';\n"
    "      ctx.strokeStyle = '#2b72cd';\n"
    "      ctx.lineWidth = 2;\n"
    "      for (var markerIndex = 0; markerIndex < scanPoints.length; markerIndex++) {\n"
    "        ctx.beginPath();\n"
    "        ctx.arc(pointX(markerIndex), pointY(scanPoints[markerIndex].rssi), 3.5, 0, Math.PI * 2);\n"
    "        ctx.fill();\n"
    "        ctx.stroke();\n"
    "      }\n"
    "    }\n"
    "  }\n"
    "\n"
    "  function renderScanStats(points) {\n"
    "    var stats = document.getElementById('rf-chart-stats');\n"
    "    if (!stats || !points || !points.length) {\n"
    "      if (stats) stats.hidden = true;\n"
    "      return;\n"
    "    }\n"
    "    var minPoint = points[0];\n"
    "    var maxPoint = points[0];\n"
    "    var sum = 0;\n"
    "    for (var i = 0; i < points.length; i++) {\n"
    "      if (Number(points[i].rssi) < Number(minPoint.rssi)) minPoint = points[i];\n"
    "      if (Number(points[i].rssi) > Number(maxPoint.rssi)) maxPoint = points[i];\n"
    "      sum += Number(points[i].rssi);\n"
    "    }\n"
    "    setText('rf-chart-min', minPoint.rssi + ' dBm · ' + minPoint.freq);\n"
    "    setText('rf-chart-avg', (sum / points.length).toFixed(1) + ' dBm');\n"
    "    setText('rf-chart-max', maxPoint.rssi + ' dBm · ' + maxPoint.freq);\n"
    "    stats.hidden = false;\n"
    "  }\n"
    "\n"
    "  function renderAcmChannels() {\n"
    "    var container = document.getElementById('rf-channel-grid');\n"
    "    if (!container) return;\n"
    "    if (!acmChannels.length) {\n"
    "      container.innerHTML = '';\n"
    "      return;\n"
    "    }\n"
    "    var html = '';\n"
    "    for (var i = 0; i < acmChannels.length; i++) {\n"
    "      var item = acmChannels[i];\n"
    "      var levelClass = item.status === '异常' ? 'rf-channel-status--bad' : 'rf-channel-status--good';\n"
    "      html += '<div class=\"rf-channel-card\">'\n"
    "        + '<div class=\"rf-channel-title\">通道' + item.channel + '</div>'\n"
    "        + '<div class=\"rf-channel-status ' + levelClass + '\">' + item.status + '</div>'\n"
    "        + '</div>';\n"
    "    }\n"
    "    container.innerHTML = html;\n"
    "  }\n"
    "\n"
    "  function setAcmButtonBusy(busy) {\n"
    "    var button = document.getElementById('rf-acm-trigger');\n"
    "    acmBusy = busy;\n"
    "    if (!button) return;\n"
    "    button.disabled = busy;\n"
    "    if (busy) button.classList.add('rf-btn-disabled');\n"
    "    else button.classList.remove('rf-btn-disabled');\n"
    "  }\n"
    "\n"
    "  function stopAcmAnimation() {\n"
    "    if (acmAnimationTimerId) {\n"
    "      clearInterval(acmAnimationTimerId);\n"
    "      acmAnimationTimerId = null;\n"
    "    }\n"
    "    acmAnimationStep = 0;\n"
    "  }\n"
    "\n"
    "  function startAcmAnimation() {\n"
    "    stopAcmAnimation();\n"
    "    acmAnimationTimerId = setInterval(function(){\n"
    "      var dots = '';\n"
    "      acmAnimationStep = (acmAnimationStep + 1) % 4;\n"
    "      for (var i = 0; i < acmAnimationStep; i++) dots += '.';\n"
    "      setText('rf-acm-summary', 'ACM校准中' + dots);\n"
    "    }, 500);\n"
    "  }\n"
    "\n"
    "  function clearAcmStatusTimer() {\n"
    "    if (acmStatusTimerId) {\n"
    "      clearTimeout(acmStatusTimerId);\n"
    "      acmStatusTimerId = null;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  function finishAcmError(message) {\n"
    "    clearAcmStatusTimer();\n"
    "    stopAcmAnimation();\n"
    "    setAcmButtonBusy(false);\n"
    "    setText('rf-acm-summary', message);\n"
    "  }\n"
    "\n"
    "  function finishAcmSuccess(channels, summary) {\n"
    "    clearAcmStatusTimer();\n"
    "    stopAcmAnimation();\n"
    "    setAcmButtonBusy(false);\n"
    "    acmChannels = channels || [];\n"
    "    setText('rf-acm-summary', summary);\n"
    "    renderAcmChannels();\n"
    "  }\n"
    "\n"
    "  function scheduleAcmStatusPoll(delayMs) {\n"
    "    clearAcmStatusTimer();\n"
    "    acmStatusTimerId = setTimeout(pollAcmStatus, delayMs);\n"
    "  }\n"
    "\n"
    "  function loadAcmResult() {\n"
    "    fetchJsonWithTimeout('/api/rf_acm/result', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (!res || res.status !== 'ok' || !res.data || !res.data.channels || !res.data.channels.length) {\n"
    "        throw new Error(res && res.message ? res.message : 'invalid acm result');\n"
    "      }\n"
    "      var channels = [];\n"
    "      for (var i = 0; i < res.data.channels.length; i++) {\n"
    "        var item = res.data.channels[i];\n"
    "        channels.push({\n"
    "          channel: item.channel,\n"
    "          status: item.status === 'error' ? '异常' : '正常'\n"
    "        });\n"
    "      }\n"
    "      finishAcmSuccess(channels, 'ACM校准完成：共 ' + (res.data.count || channels.length) + ' 个通道');\n"
    "    }).catch(function(err){\n"
    "      finishAcmError(err && err.message ? err.message : 'ACM结果格式错误或结果文件不可用');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function pollAcmStatus() {\n"
    "    if (!acmBusy || stopped) return;\n"
    "    fetchJsonWithTimeout('/api/rf_acm/status', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      var data = res && res.data ? res.data : null;\n"
    "      if (!res || res.status !== 'ok' || !data) throw new Error('invalid acm status');\n"
    "      if (data.state === 'done' && data.result_ready) {\n"
    "        setText('rf-acm-summary', data.message || 'ACM校准完成');\n"
    "        loadAcmResult();\n"
    "        return;\n"
    "      }\n"
    "      if (data.state === 'failed' || data.state === 'error') {\n"
    "        finishAcmError(data.message || 'ACM校准失败');\n"
    "        return;\n"
    "      }\n"
    "      setText('rf-acm-summary', data.message || 'ACM校准中');\n"
    "      scheduleAcmStatusPoll(1000);\n"
    "    }).catch(function(){\n"
    "      finishAcmError('ACM状态读取失败，请检查服务端运行状态');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function startAcm() {\n"
    "    if (acmBusy) return;\n"
    "    setAcmButtonBusy(true);\n"
    "    setText('rf-acm-summary', 'ACM启动中');\n"
    "    startAcmAnimation();\n"
    "    fetchJsonWithTimeout('/api/rf_acm/start', {\n"
    "      method: 'POST',\n"
    "      cache: 'no-store'\n"
    "    }, 4000).then(function(res){\n"
    "      if (!res) throw new Error('empty response');\n"
    "      if (res.status === 'ok' || res.status === 'busy') {\n"
    "        setText('rf-acm-summary', res.message || 'ACM任务已受理');\n"
    "        scheduleAcmStatusPoll(800);\n"
    "        return;\n"
    "      }\n"
    "      throw new Error(res.message || 'acm start failed');\n"
    "    }).catch(function(err){\n"
    "      finishAcmError(err && err.message ? err.message : 'ACM启动失败');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function renderStats(payload) {\n"
    "    var data = payload && payload.data ? payload.data : payload;\n"
    "    var downlink = data && data.mqtt_sub_msg_count != null ? data.mqtt_sub_msg_count : '--';\n"
    "    var uplink = data && data.spi_data_total_count != null ? data.spi_data_total_count : '--';\n"
    "    setText('rf-stat-downlink', String(downlink));\n"
    "    setText('rf-stat-uplink', String(uplink));\n"
    "    setText('rf-stats-summary', '最近更新: ' + new Date().toLocaleTimeString());\n"
    "  }\n"
    "\n"
    "  function scheduleStats(delayMs) {\n"
    "    if (statsTimerId) clearTimeout(statsTimerId);\n"
    "    statsTimerId = setTimeout(loadStats, delayMs);\n"
    "  }\n"
    "\n"
    "  function loadStats() {\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (statsInFlight) {\n"
    "      scheduleStats(500);\n"
    "      return;\n"
    "    }\n"
    "    statsInFlight = true;\n"
    "    function finishCycle() {\n"
    "      statsInFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleStats(5000);\n"
    "    }\n"
    "    fetchJsonWithTimeout('/api/rf_stats', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (res && res.status === 'ok') {\n"
    "        lastStats = res;\n"
    "        renderStats(res);\n"
    "      } else if (lastStats) {\n"
    "        renderStats(lastStats);\n"
    "      } else {\n"
    "        setText('rf-stats-summary', '统计数据暂不可用');\n"
    "      }\n"
    "      finishCycle();\n"
    "    }).catch(function(){\n"
    "      if (lastStats) {\n"
    "        renderStats(lastStats);\n"
    "      } else {\n"
    "        setText('rf-stats-summary', '统计数据读取失败');\n"
    "      }\n"
    "      finishCycle();\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function resetStats() {\n"
    "    if (!confirm('确认清零 TurMass 数据统计吗？')) return;\n"
    "    fetchJsonWithTimeout('/api/rf_stats/reset', { method: 'POST', cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (!res || res.status !== 'ok') throw new Error('reset failed');\n"
    "      lastStats = res;\n"
    "      renderStats(res);\n"
    "      setText('rf-stats-summary', '统计已清零');\n"
    "    }).catch(function(){\n"
    "      alert('清零失败，请检查文件权限或后台服务状态');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function stopScanAnimation() {\n"
    "    if (scanAnimationTimerId) {\n"
    "      clearInterval(scanAnimationTimerId);\n"
    "      scanAnimationTimerId = null;\n"
    "    }\n"
    "    scanAnimationStep = 0;\n"
    "  }\n"
    "\n"
    "  function startScanAnimation() {\n"
    "    stopScanAnimation();\n"
    "    scanAnimationTimerId = setInterval(function(){\n"
    "      var dots = '';\n"
    "      scanAnimationStep = (scanAnimationStep + 1) % 4;\n"
    "      for (var i = 0; i < scanAnimationStep; i++) dots += '.';\n"
    "      showChartPlaceholder('扫频中' + dots);\n"
    "    }, 500);\n"
    "  }\n"
    "\n"
    "  function clearScanStatusTimer() {\n"
    "    if (scanStatusTimerId) {\n"
    "      clearTimeout(scanStatusTimerId);\n"
    "      scanStatusTimerId = null;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  function finishScanError(message) {\n"
    "    clearScanStatusTimer();\n"
    "    stopScanAnimation();\n"
    "    setScanButtonBusy(false);\n"
    "    setText('rf-scan-summary', message);\n"
    "    if (!scanPoints.length) showChartPlaceholder(message);\n"
    "  }\n"
    "\n"
    "  function finishScanSuccess(points, summary) {\n"
    "    clearScanStatusTimer();\n"
    "    stopScanAnimation();\n"
    "    setScanButtonBusy(false);\n"
    "    scanPoints = points || [];\n"
    "    setText('rf-scan-summary', summary);\n"
    "    renderScanStats(scanPoints);\n"
    "    drawScanChart();\n"
    "  }\n"
    "\n"
    "  function scheduleScanStatusPoll(delayMs) {\n"
    "    clearScanStatusTimer();\n"
    "    scanStatusTimerId = setTimeout(pollScanStatus, delayMs);\n"
    "  }\n"
    "\n"
    "  function loadScanResult() {\n"
    "    fetchJsonWithTimeout('/api/rf_scan/result', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (!res || res.status !== 'ok' || !res.data || !res.data.points || !res.data.points.length) {\n"
    "        throw new Error(res && res.message ? res.message : 'invalid result');\n"
    "      }\n"
    "      finishScanSuccess(res.data.points, '扫频完成：' + (res.data.freq_start || '-') + ' - ' + (res.data.freq_stop || '-') + '，共 ' + (res.data.count || res.data.points.length) + ' 个频点');\n"
    "    }).catch(function(err){\n"
    "      finishScanError(err && err.message ? err.message : '扫频结果格式错误或结果文件不可用');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function pollScanStatus() {\n"
    "    if (!scanBusy || stopped) return;\n"
    "    fetchJsonWithTimeout('/api/rf_scan/status', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      var data = res && res.data ? res.data : null;\n"
    "      if (!res || res.status !== 'ok' || !data) throw new Error('invalid status');\n"
    "      if (data.state === 'done' && data.result_ready) {\n"
    "        setText('rf-scan-summary', data.message || '扫频完成');\n"
    "        loadScanResult();\n"
    "        return;\n"
    "      }\n"
    "      if (data.state === 'failed' || data.state === 'error') {\n"
    "        finishScanError(data.message || '扫频失败');\n"
    "        return;\n"
    "      }\n"
    "      setText('rf-scan-summary', data.message || '扫频中');\n"
    "      scheduleScanStatusPoll(1000);\n"
    "    }).catch(function(){\n"
    "      finishScanError('扫频状态读取失败，请检查服务端运行状态');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function startRfScan() {\n"
    "    if (scanBusy) return;\n"
    "    var start = document.getElementById('rf-scan-start');\n"
    "    var stop = document.getElementById('rf-scan-stop');\n"
    "    var mode = document.getElementById('rf-scan-mode');\n"
    "    var startValue = start ? start.value : '';\n"
    "    var stopValue = stop ? stop.value : '';\n"
    "    var modeValue = mode ? mode.value : '125k';\n"
    "    var normalizedStart = normalizeFreqInput(startValue);\n"
    "    var normalizedStop = normalizeFreqInput(stopValue);\n"
    "    var parsedStart = parseFreqValue(startValue);\n"
    "    var parsedStop = parseFreqValue(stopValue);\n"
    "    var parsedMode = parseModeValue(modeValue);\n"
    "\n"
    "    if (!normalizedStart || !normalizedStop || !isFinite(parsedStart) || !isFinite(parsedStop)) {\n"
    "      alert('请输入合法频点，格式例如 470.5M');\n"
    "      return;\n"
    "    }\n"
    "    if (!parsedMode) {\n"
    "      alert('模式取值必须是 62.5k、125k、250k、500k 之一');\n"
    "      return;\n"
    "    }\n"
    "    if (parsedStart > parsedStop) {\n"
    "      alert('开始频率不能大于停止频率');\n"
    "      return;\n"
    "    }\n"
    "\n"
    "    if (start) start.value = normalizedStart;\n"
    "    if (stop) stop.value = normalizedStop;\n"
    "    if (mode) mode.value = parsedMode;\n"
    "\n"
    "    setScanButtonBusy(true);\n"
    "    setText('rf-scan-summary', '扫频启动中');\n"
    "    showChartPlaceholder('扫频中');\n"
    "    startScanAnimation();\n"
    "\n"
    "    var body = 'freq_start=' + encodeURIComponent(normalizedStart)\n"
    "      + '&freq_stop=' + encodeURIComponent(normalizedStop)\n"
    "      + '&mode=' + encodeURIComponent(String(parsedMode));\n"
    "    fetchJsonWithTimeout('/api/rf_scan/start', {\n"
    "      method: 'POST',\n"
    "      headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },\n"
    "      body: body,\n"
    "      cache: 'no-store'\n"
    "    }, 4000).then(function(res){\n"
    "      if (!res) throw new Error('empty response');\n"
    "      if (res.status === 'ok' || res.status === 'busy') {\n"
    "        setText('rf-scan-summary', res.message || '扫频任务已受理');\n"
    "        scheduleScanStatusPoll(800);\n"
    "        return;\n"
    "      }\n"
    "      throw new Error(res.message || 'start failed');\n"
    "    }).catch(function(err){\n"
    "      finishScanError(err && err.message ? err.message : '扫频启动失败');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  var scanButton = document.getElementById('rf-scan-trigger');\n"
    "  if (scanButton) {\n"
    "    scanButton.addEventListener('click', startRfScan);\n"
    "  }\n"
    "\n"
    "  var acmButton = document.getElementById('rf-acm-trigger');\n"
    "  if (acmButton) {\n"
    "    acmButton.addEventListener('click', startAcm);\n"
    "  }\n"
    "\n"
    "  var resetButton = document.getElementById('rf-stats-reset');\n"
    "  if (resetButton) {\n"
    "    resetButton.addEventListener('click', resetStats);\n"
    "  }\n"
    "\n"
    "  window.addEventListener('resize', drawScanChart);\n"
    "  window.addEventListener('pagehide', function(){\n"
    "    stopped = true;\n"
    "    if (statsTimerId) {\n"
    "      clearTimeout(statsTimerId);\n"
    "      statsTimerId = null;\n"
    "    }\n"
    "    clearScanStatusTimer();\n"
    "    stopScanAnimation();\n"
    "    clearAcmStatusTimer();\n"
    "    stopAcmAnimation();\n"
    "  });\n"
    "\n"
    "  document.addEventListener('visibilitychange', function() {\n"
    "    if (document.hidden) {\n"
    "      if (statsTimerId) {\n"
    "        clearTimeout(statsTimerId);\n"
    "        statsTimerId = null;\n"
    "      }\n"
    "      clearScanStatusTimer();\n"
    "      clearAcmStatusTimer();\n"
    "      return;\n"
    "    }\n"
    "    if (!stopped && !statsInFlight) scheduleStats(100);\n"
    "    if (!stopped && scanBusy) scheduleScanStatusPoll(100);\n"
    "    if (!stopped && acmBusy) scheduleAcmStatusPoll(100);\n"
    "  });\n"
    "\n"
    "  showChartPlaceholder('等待开始扫频');\n"
    "  renderAcmChannels();\n"
    "  loadStats();\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_STATUS_NETWORK_HTML = 
    "<div class=\"status-card status-card--network\">\n"
    "  <div class=\"status-card-header\">IPv4 WAN状态</div>\n"
    "  <div class=\"status-card-body\">\n"
    "    <div class=\"status-kv-row\"><div class=\"status-kv-label\">协议</div><div class=\"status-kv-value\">%s</div></div>\n"
    "    <div class=\"status-kv-row\"><div class=\"status-kv-label\">活跃接口</div><div class=\"status-kv-value\" id=\"active-iface\">-</div></div>\n"
    "    <div class=\"status-kv-row\"><div class=\"status-kv-label\">IPv4</div><div class=\"status-kv-value\" id=\"active-ipv4\">-</div></div>\n"
    "    <div class=\"status-kv-row\"><div class=\"status-kv-label\">IPv6</div><div class=\"status-kv-value\" id=\"active-ipv6\">-</div></div>\n"
    "    <div class=\"status-kv-row\"><div class=\"status-kv-label\">网关</div><div class=\"status-kv-value\" id=\"active-gateway\">-</div></div>\n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "(function(){\n"
    "  var timerId = null;\n"
    "  var inFlight = false;\n"
    "  var stopped = false;\n"
    "\n"
    "  function fetchJsonWithTimeout(url, timeoutMs) {\n"
    "    if (typeof AbortController === 'undefined') {\n"
    "      return fetch(url).then(function(r){ return r.json(); });\n"
    "    }\n"
    "    var controller = new AbortController();\n"
    "    var timeoutId = setTimeout(function(){ controller.abort(); }, timeoutMs);\n"
    "    return fetch(url, { signal: controller.signal }).then(function(r){ return r.json(); }).finally(function(){\n"
    "      clearTimeout(timeoutId);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function scheduleNext(delayMs){\n"
    "    if (timerId) clearTimeout(timerId);\n"
    "    timerId = setTimeout(updateActiveIp, delayMs);\n"
    "  }\n"
    "\n"
    "  function fillFallback(){\n"
    "    var iface = document.getElementById('active-iface');\n"
    "    var v4 = document.getElementById('active-ipv4');\n"
    "    var v6 = document.getElementById('active-ipv6');\n"
    "    var gw = document.getElementById('active-gateway');\n"
    "    if (iface) iface.innerText = '-';\n"
    "    if (v4) v4.innerText = '-';\n"
    "    if (v6) v6.innerText = '-';\n"
    "    if (gw) gw.innerText = '-';\n"
    "  }\n"
    "\n"
    "  function finishCycle(){\n"
    "    inFlight = false;\n"
    "    if (stopped || document.hidden) return;\n"
    "    scheduleNext(3000);\n"
    "  }\n"
    "\n"
    "  function updateActiveIp(){\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (inFlight) {\n"
    "      scheduleNext(500);\n"
    "      return;\n"
    "    }\n"
    "    inFlight = true;\n"
    "    fetchJsonWithTimeout('/api/active_ip', 2500).then(function(res){\n"
    "      var iface = document.getElementById('active-iface');\n"
    "      var v4 = document.getElementById('active-ipv4');\n"
    "      var v6 = document.getElementById('active-ipv6');\n"
    "      var gw = document.getElementById('active-gateway');\n"
    "      if (iface) iface.innerText = res.iface || '-';\n"
    "      if (v4) v4.innerText = res.ipv4 || '-';\n"
    "      if (v6) v6.innerText = res.ipv6 || '-';\n"
    "      if (gw) gw.innerText = res.gateway || '-';\n"
    "      finishCycle();\n"
    "    }).catch(function(){\n"
    "      fillFallback();\n"
    "      finishCycle();\n"
    "    });\n"
    "  }\n"
    "\n"
    "  window.addEventListener('pagehide', function(){\n"
    "    stopped = true;\n"
    "    if (timerId) {\n"
    "      clearTimeout(timerId);\n"
    "      timerId = null;\n"
    "    }\n"
    "  });\n"
    "\n"
    "  document.addEventListener('visibilitychange', function() {\n"
    "    if (document.hidden) {\n"
    "      if (timerId) {\n"
    "        clearTimeout(timerId);\n"
    "        timerId = null;\n"
    "      }\n"
    "      return;\n"
    "    }\n"
    "    if (!stopped && !inFlight) scheduleNext(100);\n"
    "  });\n"
    "\n"
    "  updateActiveIp();\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_STATUS_RESOURCES_HTML = 
    "<div class=\"status-card status-card--kpi\"><div class=\"status-card-header\">硬盘使用率</div><div class=\"status-card-body status-kpi-body\"><div class=\"status-ring\"><svg class=\"status-ring-svg\" viewBox=\"0 0 100 100\" aria-hidden=\"true\"><circle class=\"ring-bg\" cx=\"50\" cy=\"50\" r=\"42\" pathLength=\"100\"></circle><circle class=\"ring-fg\" id=\"disk-ring\" cx=\"50\" cy=\"50\" r=\"42\" pathLength=\"100\" style=\"stroke-dasharray:%d 100;\"></circle></svg><span id=\"disk-percent\">%d%%</span></div><div class=\"status-kpi-meta\" id=\"disk-meta\">已用: %llu MB / 总共: %llu MB</div></div></div><div class=\"status-card status-card--kpi\"><div class=\"status-card-header\">内存RAM占用率</div><div class=\"status-card-body status-kpi-body\"><div class=\"status-ring\"><svg class=\"status-ring-svg\" viewBox=\"0 0 100 100\" aria-hidden=\"true\"><circle class=\"ring-bg\" cx=\"50\" cy=\"50\" r=\"42\" pathLength=\"100\"></circle><circle class=\"ring-fg\" id=\"mem-ring\" cx=\"50\" cy=\"50\" r=\"42\" pathLength=\"100\" style=\"stroke-dasharray:%d 100;\"></circle></svg><span id=\"mem-percent\">%d%%</span></div><div class=\"status-kpi-meta\" id=\"mem-meta\">已用: %llu MB / 总共: %llu MB</div></div></div>\n"
    "<script>\n"
    "(function() {\n"
    "  var timerId = null;\n"
    "  var inFlight = false;\n"
    "  var stopped = false;\n"
    "  var host = document.querySelector('.status-card--system .status-card-body');\n"
    "  if (host) {\n"
    "    [['gw-running','网关程序状态'],['gw-version','网关程序版本'],['gw-uptime','网关程序运行时长'],\n"
    "     ['gw-rf','射频状态（天线0～7）'],['gw-gps','GPS启用状态'],['sys-watchdog','片内看门狗']].forEach(function(item) {\n"
    "      var row=document.createElement('div'); row.className='status-kv-row';\n"
    "      var label=document.createElement('div'); label.className='status-kv-label'; label.textContent=item[1];\n"
    "      var value=document.createElement('div'); value.className='status-kv-value'; value.id=item[0]; value.textContent='读取中…';\n"
    "      row.appendChild(label); row.appendChild(value); host.appendChild(row);\n"
    "    });\n"
    "  }\n"
    "  function updateGateway(res) {\n"
    "    var gw=res.tk8710_gw || {}, e;\n"
    "    if(e=document.getElementById('sys-watchdog')) {\n"
    "      var w=res.watchdog||{}, reasons={device_missing:'设备未就绪',device_busy:'设备被占用',\n"
    "        device_open_failed:'设备打开失败',device_access_failed:'设备访问失败',\n"
    "        wrong_device_or_sysfs_missing:'驱动信息不匹配',nowayout_required:'内核保护策略未配置',\n"
    "        not_character_device:'设备节点无效',executable_missing:'服务程序缺失',launch_failed:'服务未能启动'};\n"
    "      var labels={waiting:'等待设备就绪',feeding:'喂狗正常',\n"
    "        degraded:'已喂狗，超时设置降级（'+w.actual_timeout_s+' 秒）',\n"
    "        failed:'启动失败：'+(reasons[w.reason]||'请查看日志'),stale:'喂狗状态异常',\n"
    "        stopped:w.armed?'喂狗已停止，硬件可能即将复位':'未启动',\n"
    "        fault:'喂狗故障，正在请求系统复位',unavailable:'未启动或未部署'};\n"
    "      e.textContent=labels[w.state]||'状态未知';\n"
    "      e.style.color=w.state==='feeding'?'#17633b':w.state==='waiting'?'':'#b42318';\n"
    "      if(w.state==='feeding' && typeof w.feed_interval_s==='number' && w.feed_interval_s>0 &&\n"
    "         typeof w.actual_timeout_s==='number' && w.actual_timeout_s>0) {\n"
    "        var detail=document.createElement('div'); detail.id='sys-watchdog-detail';\n"
    "        detail.style.cssText='margin-top:4px;font-size:12px;line-height:1.5;color:#667085;white-space:normal;';\n"
    "        detail.textContent='每'+w.feed_interval_s+'秒喂狗；连续约'+w.actual_timeout_s+'秒未喂狗时自动复位。';\n"
    "        e.appendChild(detail);\n"
    "      }\n"
    "    }\n"
    "    if(e=document.getElementById('gw-version')) e.textContent=typeof gw.version==='string' && gw.version ? gw.version : '未知';\n"
    "    if(e=document.getElementById('gw-running')) e.textContent=gw.running===true?'运行中':gw.running===false?'未运行':'未知';\n"
    "    if(e=document.getElementById('gw-uptime')) {\n"
    "      var n=gw.uptime_s;\n"
    "      e.textContent=typeof n==='number' && n>=0 ? Math.floor(n/3600)+'小时 '+Math.floor(n/60-Math.floor(n/3600)*60)+'分 '+Math.floor(n-Math.floor(n/60)*60)+'秒' : '--';\n"
    "    }\n"
    "    if(e=document.getElementById('gw-gps')) e.textContent=res.gps_enabled===true?'已开启':res.gps_enabled===false?'已关闭':'未知';\n"
    "    if(e=document.getElementById('gw-rf')) {\n"
    "      e.textContent='';\n"
    "      if(typeof res.rfstatus!=='string' || !/^[01]{8}$/.test(res.rfstatus)) {e.textContent='未知';return;}\n"
    "      for(var i=0;i<8;i++) {\n"
    "        var good=res.rfstatus.charAt(7-i)==='1', badge=document.createElement('span');\n"
    "        badge.textContent='天线'+i+' '+(good?'正常':'异常');\n"
    "        badge.style.cssText='display:inline-block;padding:3px 7px;margin:2px;border-radius:5px;font-size:12px;background:'+(good?'#e8f5ee':'#fff0ed')+';color:'+(good?'#17633b':'#b42318');\n"
    "        e.appendChild(badge);\n"
    "      }\n"
    "      if(gw.running!==true) e.appendChild(document.createTextNode('（最后记录）'));\n"
    "    }\n"
    "  }\n"
    "\n"
    "  function fetchJsonWithTimeout(url, timeoutMs) {\n"
    "    if (typeof AbortController === 'undefined') {\n"
    "      return fetch(url).then(function(r){ return r.json(); });\n"
    "    }\n"
    "    var controller = new AbortController();\n"
    "    var timeoutId = setTimeout(function() { controller.abort(); }, timeoutMs);\n"
    "    return fetch(url, { signal: controller.signal }).then(function(r){ return r.json(); }).finally(function(){\n"
    "      clearTimeout(timeoutId);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function scheduleNext(delayMs) {\n"
    "    if (timerId) clearTimeout(timerId);\n"
    "    timerId = setTimeout(updateSystemInfo, delayMs);\n"
    "  }\n"
    "\n"
    "  function finishCycle() {\n"
    "    inFlight = false;\n"
    "    if (stopped || document.hidden) return;\n"
    "    scheduleNext(3000);\n"
    "  }\n"
    "\n"
    "  function updateSystemInfo() {\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (inFlight) {\n"
    "      scheduleNext(500);\n"
    "      return;\n"
    "    }\n"
    "    inFlight = true;\n"
    "    fetchJsonWithTimeout('/api/system_info', 2500).then(function(res){\n"
    "      var e;\n"
    "      updateGateway(res);\n"
    "      if(e=document.getElementById('sys-hostname')) e.innerText=res.hostname;\n"
    "      if(e=document.getElementById('sys-model')) e.innerText=res.model;\n"
    "      if(e=document.getElementById('sys-arch')) e.innerText=res.arch;\n"
    "      if(e=document.getElementById('sys-coords')) e.innerText=(res.device_coords && res.device_coords.trim()) ? res.device_coords : '--';\n"
    "      if(e=document.getElementById('sys-firmware')) e.innerText=res.firmware_version;\n"
    "      if(e=document.getElementById('sys-kernel')) e.innerText=res.kernel_version;\n"
    "      if(e=document.getElementById('sys-time')) e.innerText=res.local_time;\n"
    "      if(e=document.getElementById('sys-uptime')) e.innerText=res.uptime;\n"
    "      if(e=document.getElementById('sys-load')) e.innerText=res.load_avg[0].toFixed(2)+', '+res.load_avg[1].toFixed(2)+', '+res.load_avg[2].toFixed(2);\n"
    "      if(e=document.getElementById('sys-app')) e.innerText=res.app_version;\n"
    "\n"
    "      if(e=document.getElementById('disk-ring')) e.style.strokeDasharray=res.disk_percent+' 100';\n"
    "      if(e=document.getElementById('disk-percent')) e.innerText=res.disk_percent+'%%';\n"
    "      if(e=document.getElementById('disk-meta')) e.innerText='已用: '+res.disk_used+' MB / 总共: '+res.disk_total+' MB';\n"
    "\n"
    "      if(e=document.getElementById('mem-ring')) e.style.strokeDasharray=res.mem_percent+' 100';\n"
    "      if(e=document.getElementById('mem-percent')) e.innerText=res.mem_percent+'%%';\n"
    "      if(e=document.getElementById('mem-meta')) e.innerText='已用: '+res.mem_used+' MB / 总共: '+res.mem_total+' MB';\n"
    "      finishCycle();\n"
    "    }).catch(function(){\n"
    "      updateGateway({});\n"
    "      finishCycle();\n"
    "    });\n"
    "  }\n"
    "\n"
    "  window.addEventListener('pagehide', function() {\n"
    "    stopped = true;\n"
    "    if (timerId) {\n"
    "      clearTimeout(timerId);\n"
    "      timerId = null;\n"
    "    }\n"
    "  });\n"
    "\n"
    "  document.addEventListener('visibilitychange', function() {\n"
    "    if (document.hidden) {\n"
    "      if (timerId) {\n"
    "        clearTimeout(timerId);\n"
    "        timerId = null;\n"
    "      }\n"
    "      return;\n"
    "    }\n"
    "    if (!stopped && !inFlight) scheduleNext(100);\n"
    "  });\n"
    "\n"
    "  updateSystemInfo();\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_STATUS_SYSTEM_HTML = 
    "<div class=\"status-card status-card--system\"><div class=\"status-card-header\">系统信息</div><div class=\"status-card-body\"><div class=\"status-kv-row\"><div class=\"status-kv-label\">主机名</div><div class=\"status-kv-value\" id=\"sys-hostname\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">型号</div><div class=\"status-kv-value\" id=\"sys-model\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">架构</div><div class=\"status-kv-value\" id=\"sys-arch\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">设备坐标</div><div class=\"status-kv-value\" id=\"sys-coords\" style=\"overflow-wrap:anywhere;word-break:break-word;\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">通信软件版本</div><div class=\"status-kv-value\" id=\"sys-firmware\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">内核版本</div><div class=\"status-kv-value\" id=\"sys-kernel\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">本地时间</div><div class=\"status-kv-value\" id=\"sys-time\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">系统运行时长</div><div class=\"status-kv-value\" id=\"sys-uptime\">%s</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">平均负载</div><div class=\"status-kv-value\" id=\"sys-load\">%.2f, %.2f, %.2f</div></div><div class=\"status-kv-row\"><div class=\"status-kv-label\">Web管理版本</div><div class=\"status-kv-value\" id=\"sys-app\">%s</div></div></div></div>\n"
    "";

static const char *RES_HTML_STATUS_TRAFFIC_HTML = 
    "<div class=\"status-card status-card--traffic\">\n"
    "  <div class=\"status-card-header\">网络状态</div>\n"
    "  <div class=\"status-card-body\" style=\"padding: 16px 24px; display: flex; flex-direction: column; height: 100%; box-sizing: border-box;\">\n"
    "    \n"
    "    <div style=\"display: flex; justify-content: space-between; margin-bottom: 12px;\">\n"
    "      <div>\n"
    "        <div style=\"font-size: 13px; color: var(--tm-text-title); font-weight: 600; display: flex; align-items: center; gap: 6px;\">\n"
    "          <span style=\"display:inline-block;width:10px;height:10px;background:#f39c12;border-radius:2px;\"></span> 上行 (Upload)\n"
    "        </div>\n"
    "        <div style=\"color: #f39c12; font-weight: bold; font-size: 18px; margin-top: 4px;\" id=\"rate-tx\">0 B/s</div>\n"
    "      </div>\n"
    "      <div style=\"text-align: right;\">\n"
    "        <div style=\"font-size: 13px; color: var(--tm-text-title); font-weight: 600; display: flex; align-items: center; gap: 6px; justify-content: flex-end;\">\n"
    "          <span style=\"display:inline-block;width:10px;height:10px;background:#7f8c8d;border-radius:2px;\"></span> 下行 (Download)\n"
    "        </div>\n"
    "        <div style=\"color: #7f8c8d; font-weight: bold; font-size: 18px; margin-top: 4px;\" id=\"rate-rx\">0 B/s</div>\n"
    "      </div>\n"
    "    </div>\n"
    "\n"
    "    <div style=\"display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;\">\n"
    "      <div>\n"
    "        <div style=\"font-size: 13px; color: var(--tm-text-title); font-weight: 600; display: flex; align-items: center; gap: 6px;\">\n"
    "          <span style=\"display:inline-block;width:10px;height:10px;background:#3498db;border-radius:2px;\"></span> 平均延迟\n"
    "        </div>\n"
    "        <div style=\"color: #3498db; font-weight: bold; font-size: 18px; margin-top: 4px;\" id=\"latency-avg\">-- ms</div>\n"
    "      </div>\n"
    "      <div style=\"text-align: right;\">\n"
    "        <div style=\"font-size: 13px; color: var(--tm-text-title); font-weight: 600; display: flex; align-items: center; gap: 6px; justify-content: flex-end;\">\n"
    "          <span style=\"display:inline-block;width:10px;height:10px;background:#9b59b6;border-radius:2px;\"></span> 抖动\n"
    "        </div>\n"
    "        <div style=\"color: #9b59b6; font-weight: bold; font-size: 18px; margin-top: 4px;\" id=\"latency-jitter\">-- ms</div>\n"
    "      </div>\n"
    "    </div>\n"
    "    \n"
    "    <div style=\"flex: 1; min-height: 220px; position: relative;\" id=\"chart-container\">\n"
    "      <canvas id=\"traffic-chart\" style=\"position: absolute; left: 0; top: 0; width: 100%; height: 100%;\"></canvas>\n"
    "    </div>\n"
    "    \n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "(function(){\n"
    "  var lastTx = -1, lastRx = -1, lastTime = 0;\n"
    "  var maxPoints = 10;\n"
    "  var historyTx = Array(maxPoints).fill(0);\n"
    "  var historyRx = Array(maxPoints).fill(0);\n"
    "  var inFlight = false;\n"
    "  var qualityInFlight = false;\n"
    "  var reqSeq = 0;\n"
    "  var appliedSeq = 0;\n"
    "  var samplesCount = 0;\n"
    "  var trafficTimerId = null;\n"
    "  var qualityTimerId = null;\n"
    "  var stopped = false;\n"
    "\n"
    "  function fetchJsonWithTimeout(url, timeoutMs) {\n"
    "    if (typeof AbortController === 'undefined') {\n"
    "      return fetch(url).then(function(r) { return r.json(); });\n"
    "    }\n"
    "    var controller = new AbortController();\n"
    "    var timeoutId = setTimeout(function(){ controller.abort(); }, timeoutMs);\n"
    "    return fetch(url, { signal: controller.signal }).then(function(r) { return r.json(); }).finally(function(){\n"
    "      clearTimeout(timeoutId);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function formatBytes(bytes) {\n"
    "    if (bytes === 0) return '0 B';\n"
    "    var k = 1024, sizes = ['B', 'KB', 'MB', 'GB', 'TB'], i = Math.floor(Math.log(bytes) / Math.log(k));\n"
    "    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];\n"
    "  }\n"
    "\n"
    "  function drawChart() {\n"
    "    var container = document.getElementById('chart-container');\n"
    "    var canvas = document.getElementById('traffic-chart');\n"
    "    if(!canvas || !container) return;\n"
    "    \n"
    "    var rect = container.getBoundingClientRect();\n"
    "    // 兼容高分辨率屏幕，防止画布模糊\n"
    "    var dpr = window.devicePixelRatio || 1;\n"
    "    canvas.width = Math.max(1, Math.round(rect.width * dpr));\n"
    "    canvas.height = Math.max(1, Math.round(rect.height * dpr));\n"
    "    \n"
    "    var ctx = canvas.getContext('2d');\n"
    "    if (!ctx) return;\n"
    "    if (ctx.setTransform) {\n"
    "      ctx.setTransform(1, 0, 0, 1, 0, 0);\n"
    "    }\n"
    "    ctx.scale(dpr, dpr);\n"
    "    \n"
    "    var w = rect.width;\n"
    "    var h = rect.height;\n"
    "\n"
    "    ctx.clearRect(0, 0, w, h);\n"
    "\n"
    "    // 确定 Y 轴最大值（抗离群值）\n"
    "    var maxVal = 100; // 最小比例尺，避免数值太小导致 UI 难看\n"
    "    var allVals = historyTx.concat(historyRx).filter(function(v) { return v > 0; });\n"
    "    allVals.sort(function(a, b) { return b - a; }); // desc\n"
    "    if (allVals.length > 1) {\n"
    "      // 若最大值比次大值大 5 倍以上，认为是离群峰值，使用次大值\n"
    "      if (allVals[0] > allVals[1] * 5) {\n"
    "        maxVal = allVals[1];\n"
    "      } else {\n"
    "        maxVal = allVals[0];\n"
    "      }\n"
    "    } else if (allVals.length === 1) {\n"
    "      maxVal = allVals[0];\n"
    "    }\n"
    "    maxVal = maxVal * 1.2; // 顶部预留 20% 的留白\n"
    "\n"
    "    var paddingLeft = 55, paddingBottom = 24, paddingTop = 10, paddingRight = 10;\n"
    "    var chartW = w - paddingLeft - paddingRight;\n"
    "    var chartH = h - paddingTop - paddingBottom;\n"
    "\n"
    "    // 绘制网格线和 Y 轴标签 (4等分)\n"
    "    ctx.fillStyle = '#4f6783';\n"
    "    ctx.font = '11px sans-serif';\n"
    "    ctx.textAlign = 'right';\n"
    "    ctx.textBaseline = 'middle';\n"
    "    \n"
    "    for(var j=0; j<=4; j++) {\n"
    "        var yVal = maxVal * (j/4);\n"
    "        var yPos = h - paddingBottom - (chartH * (j/4));\n"
    "        \n"
    "        ctx.fillText(formatBytes(yVal) + '/s', paddingLeft - 8, yPos);\n"
    "        \n"
    "        ctx.beginPath();\n"
    "        // 底部基准线用实线，网格线用浅色细线\n"
    "        ctx.strokeStyle = j === 0 ? '#d9e5f3' : '#f0f4f8';\n"
    "        ctx.lineWidth = j === 0 ? 2 : 1;\n"
    "        ctx.moveTo(paddingLeft, yPos);\n"
    "        ctx.lineTo(w - paddingRight, yPos);\n"
    "        ctx.stroke();\n"
    "    }\n"
    "\n"
    "    // 绘制 X 轴标签和双柱状图\n"
    "    ctx.textAlign = 'center';\n"
    "    ctx.textBaseline = 'top';\n"
    "    var barTotalWidth = chartW / maxPoints;\n"
    "    var barWidth = barTotalWidth * 0.35;\n"
    "    var gap = barTotalWidth * 0.1;\n"
    "\n"
    "    for(var i=0; i<maxPoints; i++) {\n"
    "        var xCenter = paddingLeft + i * barTotalWidth + barTotalWidth/2;\n"
    "        \n"
    "        // 绘制 X 轴时间标签（如 -27s, -24s ... 0s）\n"
    "        var timeLabel = '-' + ((maxPoints - 1 - i) * 3) + 's';\n"
    "        if (i === maxPoints - 1) timeLabel = '0s';\n"
    "        ctx.fillText(timeLabel, xCenter, h - paddingBottom + 8);\n"
    "\n"
    "        // 绘制下行数据柱 (灰色)\n"
    "        var rxH = (historyRx[i] / maxVal) * chartH;\n"
    "        if (historyRx[i] > 0 && rxH < 3) rxH = 3;\n"
    "        ctx.fillStyle = '#7f8c8d';\n"
    "        ctx.fillRect(xCenter - barWidth - gap/2, h - paddingBottom - rxH, barWidth, rxH);\n"
    "\n"
    "        // 绘制上行数据柱 (黄色)\n"
    "        var txH = (historyTx[i] / maxVal) * chartH;\n"
    "        if (historyTx[i] > 0 && txH < 3) txH = 3;\n"
    "        ctx.fillStyle = '#f39c12';\n"
    "        ctx.fillRect(xCenter + gap/2, h - paddingBottom - txH, barWidth, txH);\n"
    "    }\n"
    "\n"
    "  }\n"
    "\n"
    "  function updateTraffic() {\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (inFlight) {\n"
    "      scheduleTrafficNext(500);\n"
    "      return;\n"
    "    }\n"
    "    inFlight = true;\n"
    "    var seq = ++reqSeq;\n"
    "    fetchJsonWithTimeout('/api/traffic', 2500).then(function(data) {\n"
    "      // 丢弃过期响应，避免乱序返回导致“文字和图表不一致”\n"
    "      if (seq < appliedSeq) {\n"
    "        inFlight = false;\n"
    "        scheduleTrafficNext(3000);\n"
    "        return;\n"
    "      }\n"
    "      appliedSeq = seq;\n"
    "      var now = Date.now();\n"
    "      if (lastTime > 0) {\n"
    "        var dt = (now - lastTime) / 1000;\n"
    "        if (dt <= 0) {\n"
    "          inFlight = false;\n"
    "          scheduleTrafficNext(3000);\n"
    "          return;\n"
    "        }\n"
    "        // 过滤异常短周期请求，避免比例尺瞬间拉爆；阈值贴近3秒轮询的一半\n"
    "        if (dt < 1.0) {\n"
    "          lastTx = data.tx_bytes;\n"
    "          lastRx = data.rx_bytes;\n"
    "          lastTime = now;\n"
    "          inFlight = false;\n"
    "          scheduleTrafficNext(3000);\n"
    "          return;\n"
    "        }\n"
    "        var rateTx = (data.tx_bytes - lastTx) / dt;\n"
    "        var rateRx = (data.rx_bytes - lastRx) / dt;\n"
    "        rateTx = Math.max(0, rateTx);\n"
    "        rateRx = Math.max(0, rateRx);\n"
    "\n"
    "        document.getElementById('rate-tx').innerText = formatBytes(rateTx) + '/s';\n"
    "        document.getElementById('rate-rx').innerText = formatBytes(rateRx) + '/s';\n"
    "\n"
    "        samplesCount++;\n"
    "        historyTx.shift(); historyTx.push(rateTx);\n"
    "        historyRx.shift(); historyRx.push(rateRx);\n"
    "\n"
    "\n"
    "        drawChart();\n"
    "      } else {\n"
    "        // 首次仅记录累计字节，等待正常 3 秒周期再计算速率\n"
    "        setTimeout(drawChart, 100);\n"
    "      }\n"
    "      lastTx = data.tx_bytes;\n"
    "      lastRx = data.rx_bytes;\n"
    "      lastTime = now;\n"
    "      inFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleTrafficNext(3000);\n"
    "    }).catch(function(){\n"
    "      inFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleTrafficNext(3000);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function updateNetworkQuality() {\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (qualityInFlight) {\n"
    "      scheduleQualityNext(500);\n"
    "      return;\n"
    "    }\n"
    "    qualityInFlight = true;\n"
    "    fetchJsonWithTimeout('/api/network_quality', 3500).then(function(data) {\n"
    "      var avg = document.getElementById('latency-avg');\n"
    "      var jitter = document.getElementById('latency-jitter');\n"
    "      if (data.ok) {\n"
    "        if (avg) avg.innerText = Number(data.avg_latency_ms).toFixed(1) + ' ms';\n"
    "        if (jitter) jitter.innerText = Number(data.jitter_ms).toFixed(1) + ' ms';\n"
    "      } else {\n"
    "        if (avg) avg.innerText = '-- ms';\n"
    "        if (jitter) jitter.innerText = '-- ms';\n"
    "      }\n"
    "      qualityInFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleQualityNext(8000);\n"
    "    }).catch(function(){\n"
    "      var avg = document.getElementById('latency-avg');\n"
    "      var jitter = document.getElementById('latency-jitter');\n"
    "      if (avg) avg.innerText = '-- ms';\n"
    "      if (jitter) jitter.innerText = '-- ms';\n"
    "      qualityInFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleQualityNext(8000);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function scheduleTrafficNext(delayMs) {\n"
    "    if (trafficTimerId) clearTimeout(trafficTimerId);\n"
    "    trafficTimerId = setTimeout(updateTraffic, delayMs);\n"
    "  }\n"
    "\n"
    "  function scheduleQualityNext(delayMs) {\n"
    "    if (qualityTimerId) clearTimeout(qualityTimerId);\n"
    "    qualityTimerId = setTimeout(updateNetworkQuality, delayMs);\n"
    "  }\n"
    "\n"
    "  function onResize() {\n"
    "    drawChart();\n"
    "  }\n"
    "\n"
    "  function cleanupStatusTraffic() {\n"
    "    stopped = true;\n"
    "    if (trafficTimerId) {\n"
    "      clearTimeout(trafficTimerId);\n"
    "      trafficTimerId = null;\n"
    "    }\n"
    "    if (qualityTimerId) {\n"
    "      clearTimeout(qualityTimerId);\n"
    "      qualityTimerId = null;\n"
    "    }\n"
    "    window.removeEventListener('resize', onResize);\n"
    "  }\n"
    "\n"
    "  updateTraffic();\n"
    "  updateNetworkQuality();\n"
    "  window.addEventListener('resize', onResize); // 窗口大小改变时重绘\n"
    "  window.addEventListener('pagehide', cleanupStatusTraffic);\n"
    "  document.addEventListener('visibilitychange', function() {\n"
    "    if (document.hidden) {\n"
    "      if (trafficTimerId) {\n"
    "        clearTimeout(trafficTimerId);\n"
    "        trafficTimerId = null;\n"
    "      }\n"
    "      if (qualityTimerId) {\n"
    "        clearTimeout(qualityTimerId);\n"
    "        qualityTimerId = null;\n"
    "      }\n"
    "      return;\n"
    "    }\n"
    "    if (!stopped && !inFlight) scheduleTrafficNext(100);\n"
    "    if (!stopped && !qualityInFlight) scheduleQualityNext(100);\n"
    "  });\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_STATUS_TRAFFIC_STATS_HTML = 
    "<div class=\"status-card status-card--traffic-stats\">\n"
    "  <div class=\"status-card-header\">流量统计</div>\n"
    "  <div class=\"status-card-body traffic-stats-body\">\n"
    "    <div class=\"traffic-stat-item\">\n"
    "      <div class=\"traffic-stat-main\">\n"
    "        <div class=\"traffic-stat-name\">网口流量</div>\n"
    "        <div class=\"traffic-stat-value\" id=\"traffic-stat-eth0\">--</div>\n"
    "        <div class=\"traffic-stat-detail\" id=\"traffic-stat-eth0-detail\"></div>\n"
    "      </div>\n"
    "      <button type=\"button\" class=\"btn traffic-stat-reset\" onclick=\"resetTrafficStat('eth0', '网口(eth0)')\">清零</button>\n"
    "    </div>\n"
    "    <div class=\"traffic-stat-item\">\n"
    "      <div class=\"traffic-stat-main\">\n"
    "        <div class=\"traffic-stat-name\">4G流量</div>\n"
    "        <div class=\"traffic-stat-value\" id=\"traffic-stat-usb0\">--</div>\n"
    "        <div class=\"traffic-stat-detail\" id=\"traffic-stat-usb0-detail\"></div>\n"
    "      </div>\n"
    "      <button type=\"button\" class=\"btn traffic-stat-reset\" onclick=\"resetTrafficStat('usb0', '4G')\">清零</button>\n"
    "    </div>\n"
    "    <div class=\"traffic-stat-item\">\n"
    "      <div class=\"traffic-stat-main\">\n"
    "        <div class=\"traffic-stat-name\">WiFi流量</div>\n"
    "        <div class=\"traffic-stat-value\" id=\"traffic-stat-wlan0\">--</div>\n"
    "        <div class=\"traffic-stat-detail\" id=\"traffic-stat-wlan0-detail\"></div>\n"
    "      </div>\n"
    "      <button type=\"button\" class=\"btn traffic-stat-reset\" onclick=\"resetTrafficStat('wlan0', 'WiFi')\">清零</button>\n"
    "    </div>\n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "(function(){\n"
    "  var lastTrafficStats = null;\n"
    "  var trafficStatsInFlight = false;\n"
    "  var timerId = null;\n"
    "  var stopped = false;\n"
    "\n"
    "  function fetchJsonWithTimeout(url, options, timeoutMs) {\n"
    "    if (typeof AbortController === 'undefined') {\n"
    "      return fetch(url, options || {}).then(function(r){ return r.json(); });\n"
    "    }\n"
    "    var controller = new AbortController();\n"
    "    var timeoutId = setTimeout(function(){ controller.abort(); }, timeoutMs);\n"
    "    var opts = options || {};\n"
    "    opts.signal = controller.signal;\n"
    "    return fetch(url, opts).then(function(r){ return r.json(); }).finally(function(){\n"
    "      clearTimeout(timeoutId);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function formatTrafficBytes(bytes) {\n"
    "    bytes = Number(bytes) || 0;\n"
    "    if (bytes < 1024) return bytes + ' B';\n"
    "    var units = ['KB', 'MB', 'GB', 'TB'];\n"
    "    var value = bytes / 1024;\n"
    "    var idx = 0;\n"
    "    while (value >= 1024 && idx < units.length - 1) {\n"
    "      value = value / 1024;\n"
    "      idx++;\n"
    "    }\n"
    "    return value.toFixed(value >= 100 ? 0 : value >= 10 ? 1 : 2) + ' ' + units[idx];\n"
    "  }\n"
    "\n"
    "  function setTrafficStatText(id, text) {\n"
    "    var el = document.getElementById(id);\n"
    "    if (el) el.innerText = text;\n"
    "  }\n"
    "\n"
    "  function renderTrafficStats(payload) {\n"
    "    var data = payload && payload.data ? payload.data : payload;\n"
    "    var interfaces = data && data.interfaces ? data.interfaces : {};\n"
    "    function render(iface, item) {\n"
    "      if (!item || item.present === false) {\n"
    "        setTrafficStatText('traffic-stat-' + iface, '未检测到');\n"
    "        setTrafficStatText('traffic-stat-' + iface + '-detail', '');\n"
    "        return;\n"
    "      }\n"
    "      setTrafficStatText('traffic-stat-' + iface, '总计 ' + formatTrafficBytes(item.total_bytes));\n"
    "      setTrafficStatText('traffic-stat-' + iface + '-detail',\n"
    "        '接收 ' + formatTrafficBytes(item.rx_bytes) + ' / 发送 ' + formatTrafficBytes(item.tx_bytes));\n"
    "    }\n"
    "    render('eth0', interfaces.eth0);\n"
    "    render('usb0', interfaces.usb0);\n"
    "    render('wlan0', interfaces.wlan0);\n"
    "  }\n"
    "\n"
    "  function loadTrafficStats() {\n"
    "    if (stopped || document.hidden) return;\n"
    "    if (trafficStatsInFlight) {\n"
    "      scheduleNext(500);\n"
    "      return;\n"
    "    }\n"
    "    trafficStatsInFlight = true;\n"
    "    function finishCycle() {\n"
    "      trafficStatsInFlight = false;\n"
    "      if (stopped || document.hidden) return;\n"
    "      scheduleNext(35000);\n"
    "    }\n"
    "    fetchJsonWithTimeout('/api/traffic_stats', { cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (res && res.ok !== false) {\n"
    "        lastTrafficStats = res;\n"
    "        renderTrafficStats(res);\n"
    "      } else if (lastTrafficStats) {\n"
    "        renderTrafficStats(lastTrafficStats);\n"
    "      }\n"
    "      finishCycle();\n"
    "    }).catch(function(){\n"
    "      if (lastTrafficStats) renderTrafficStats(lastTrafficStats);\n"
    "      finishCycle();\n"
    "    });\n"
    "  }\n"
    "\n"
    "  function scheduleNext(delayMs) {\n"
    "    if (timerId) clearTimeout(timerId);\n"
    "    timerId = setTimeout(loadTrafficStats, delayMs);\n"
    "  }\n"
    "\n"
    "  window.resetTrafficStat = function(iface, label) {\n"
    "    if (!confirm('确认清零' + label + '的流量统计吗？')) return;\n"
    "    fetchJsonWithTimeout('/api/traffic_stats/reset?iface=' + encodeURIComponent(iface), { method: 'POST', cache: 'no-store' }, 4000).then(function(res){\n"
    "      if (!res || res.status !== 'ok') throw new Error('reset failed');\n"
    "      loadTrafficStats();\n"
    "    }).catch(function(){\n"
    "      alert('清零失败，请检查文件权限或后台服务状态');\n"
    "    });\n"
    "  };\n"
    "\n"
    "  window.addEventListener('pagehide', function(){\n"
    "    stopped = true;\n"
    "    if (timerId) {\n"
    "      clearTimeout(timerId);\n"
    "      timerId = null;\n"
    "    }\n"
    "  });\n"
    "\n"
    "  document.addEventListener('visibilitychange', function() {\n"
    "    if (document.hidden) {\n"
    "      if (timerId) {\n"
    "        clearTimeout(timerId);\n"
    "        timerId = null;\n"
    "      }\n"
    "      return;\n"
    "    }\n"
    "    if (!stopped && !trafficStatsInFlight) scheduleNext(100);\n"
    "  });\n"
    "\n"
    "  loadTrafficStats();\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_UPGRADE_FIRMWARE_HTML = 
    "<div class=\"panel\">\n"
    "  <div class=\"panel-header\">固件升级</div>\n"
    "  <div class=\"panel-body\">\n"
    "    <div class=\"alert alert-warning\">注意：升级过程中请勿断电，升级完成后设备将自动重启。</div>\n"
    "    <div id=\"upload-form\">\n"
    "      <div class=\"form-group\">\n"
    "        <label class=\"form-label\">选择固件 (.swu)</label>\n"
    "        <input type=\"file\" id=\"firmware-file\" accept=\".swu\">\n"
    "      </div>\n"
    "      <div class=\"form-group\">\n"
    "        <label class=\"form-label\"></label>\n"
    "        <button onclick=\"startUpgrade()\" class=\"btn\">开始升级</button>\n"
    "      </div>\n"
    "    </div>\n"
    "    <div id=\"progress-container\" style=\"display:none; padding: 20px;\">\n"
    "      <div style=\"margin-bottom: 10px;\">正在升级中，请勿断电... <span id=\"progress-text\">0</span></div>\n"
    "      <div class=\"progress-container\">\n"
    "        <div id=\"progress-bar\" class=\"progress-bar\" style=\"width:0\">0</div>\n"
    "      </div>\n"
    "      <div id=\"upgrade-status\" style=\"margin-top: 10px; color: #666;\">正在上传文件...</div>\n"
    "    </div>\n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "var UPLOAD_CHUNK_SIZE = 512 * 1024;\n"
    "var PERCENT_SIGN = String.fromCharCode(37);\n"
    "\n"
    "function startUpgrade() {\n"
    "  var fileInput = document.getElementById('firmware-file');\n"
    "  var file = fileInput.files[0];\n"
    "  if (!file) {\n"
    "    alert('请选择固件文件');\n"
    "    return;\n"
    "  }\n"
    "  if (!/\\.swu$/i.test(file.name)) {\n"
    "    alert('请选择 .swu 固件文件');\n"
    "    return;\n"
    "  }\n"
    "  document.getElementById('upload-form').style.display = 'none';\n"
    "  document.getElementById('progress-container').style.display = 'block';\n"
    "  updateProgress(0, '正在上传文件...');\n"
    "\n"
    "  uploadFileInChunks(file, 0, function() {\n"
    "    startUpgradeInstall();\n"
    "  }, function(message) {\n"
    "    alert(message);\n"
    "    resetForm();\n"
    "  });\n"
    "}\n"
    "\n"
    "function updateProgress(percent, text) {\n"
    "  document.getElementById('progress-bar').style.width = percent + PERCENT_SIGN;\n"
    "  document.getElementById('progress-bar').innerText = percent + PERCENT_SIGN;\n"
    "  document.getElementById('progress-text').innerText = percent + PERCENT_SIGN;\n"
    "  if (text) document.getElementById('upgrade-status').innerText = text;\n"
    "}\n"
    "\n"
    "function formatRequestError(xhr, prefix) {\n"
    "  var text = xhr && xhr.responseText ? xhr.responseText.trim() : '';\n"
    "  var code = xhr ? xhr.status : 0;\n"
    "  if (!text) text = 'HTTP ' + code;\n"
    "  return prefix + ': ' + text;\n"
    "}\n"
    "\n"
    "function uploadFileInChunks(file, offset, onSuccess, onError) {\n"
    "  var end = Math.min(offset + UPLOAD_CHUNK_SIZE, file.size);\n"
    "  var chunk = file.slice(offset, end);\n"
    "  var xhr = new XMLHttpRequest();\n"
    "  var url = '/upload?file=' + encodeURIComponent('image.swu') + '&offset=' + offset;\n"
    "\n"
    "  xhr.upload.addEventListener('progress', function(e) {\n"
    "    if (!e.lengthComputable) return;\n"
    "    var uploaded = offset + e.loaded;\n"
    "    var percent = Math.min(90, Math.round((uploaded / file.size) * 90));\n"
    "    updateProgress(percent, '正在上传文件... ' + Math.min(100, Math.round((uploaded / file.size) * 100)) + PERCENT_SIGN);\n"
    "  });\n"
    "\n"
    "  xhr.onreadystatechange = function() {\n"
    "    if (xhr.readyState !== 4) return;\n"
    "    if (xhr.status !== 200) {\n"
    "      onError(formatRequestError(xhr, '上传失败'));\n"
    "      return;\n"
    "    }\n"
    "\n"
    "    var nextOffset = end;\n"
    "    var percent = Math.min(90, Math.round((nextOffset / file.size) * 90));\n"
    "    updateProgress(percent, nextOffset >= file.size ? '文件上传完成，正在启动升级...' : '正在上传文件... ' + Math.min(100, Math.round((nextOffset / file.size) * 100)) + PERCENT_SIGN);\n"
    "\n"
    "    if (nextOffset >= file.size) {\n"
    "      onSuccess();\n"
    "      return;\n"
    "    }\n"
    "    uploadFileInChunks(file, nextOffset, onSuccess, onError);\n"
    "  };\n"
    "\n"
    "  xhr.onerror = function() {\n"
    "    onError('上传失败: 网络异常');\n"
    "  };\n"
    "\n"
    "  xhr.open('POST', url, true);\n"
    "  xhr.send(chunk);\n"
    "}\n"
    "\n"
    "function startUpgradeInstall() {\n"
    "  var xhr = new XMLHttpRequest();\n"
    "  xhr.onreadystatechange = function() {\n"
    "    if (xhr.readyState !== 4) return;\n"
    "    if (xhr.status === 200) {\n"
    "      updateProgress(92, '文件上传完成，正在写入固件...');\n"
    "      checkUpgradeStatus();\n"
    "    } else {\n"
    "      alert(formatRequestError(xhr, '启动升级失败'));\n"
    "      resetForm();\n"
    "    }\n"
    "  };\n"
    "  xhr.onerror = function() {\n"
    "    alert('启动升级失败: 网络异常');\n"
    "    resetForm();\n"
    "  };\n"
    "  xhr.open('POST', '/upload/start', true);\n"
    "  xhr.send('');\n"
    "}\n"
    "\n"
    "function checkUpgradeStatus() {\n"
    "  var interval = setInterval(function() {\n"
    "    var xhr = new XMLHttpRequest();\n"
    "    xhr.open('GET', '/api/upgrade_status', true);\n"
    "    xhr.onreadystatechange = function() {\n"
    "      if (xhr.readyState === 4 && xhr.status === 200) {\n"
    "        var res = JSON.parse(xhr.responseText);\n"
    "        if (res.status === 'done') {\n"
    "          clearInterval(interval);\n"
    "          updateProgress(100, '升级成功，设备即将重启...');\n"
    "          setTimeout(function() { location.reload(); }, 5000);\n"
    "        } else if (res.status === 'error') {\n"
    "          clearInterval(interval);\n"
    "          alert('升级失败: ' + res.message);\n"
    "          resetForm();\n"
    "        } else if (res.status === 'installing') {\n"
    "          var current = parseInt(document.getElementById('progress-bar').style.width);\n"
    "          if (isNaN(current) || current < 92) current = 92;\n"
    "          if (current < 99) updateProgress(current + 1, '正在安装固件...');\n"
    "        }\n"
    "      }\n"
    "    };\n"
    "    xhr.send();\n"
    "  }, 1000);\n"
    "}\n"
    "\n"
    "function resetForm() {\n"
    "  document.getElementById('upload-form').style.display = 'block';\n"
    "  document.getElementById('progress-container').style.display = 'none';\n"
    "}\n"
    "</script>\n"
    "";

static const char *RES_HTML_UPGRADE_LOGS_HTML = 
    "<div class=\"panel\">\n"
    "  <div class=\"panel-header\">日志导出</div>\n"
    "  <div class=\"panel-body\" style=\"padding:18px 20px\">\n"
    "    <p>按类型选择日志，后台打包为一个压缩文件。导出不会删除原始日志。</p>\n"
    "    <div id=\"log-types\" style=\"display:flex;flex-wrap:wrap;gap:14px;margin:16px 0\">\n"
    "      <label><input type=\"checkbox\" value=\"web\" checked> Web服务</label>\n"
    "      <label><input type=\"checkbox\" value=\"mqtt\" checked> MQTT通信</label>\n"
    "      <label><input type=\"checkbox\" value=\"tk8710\" checked> TK8710网关</label>\n"
    "      <label><input type=\"checkbox\" value=\"daemon\"> 守护进程</label>\n"
    "      <label><input type=\"checkbox\" value=\"system\"> 系统日志</label>\n"
    "      <label><input type=\"checkbox\" value=\"upgrade\"> 升级日志</label>\n"
    "      <label><input type=\"checkbox\" value=\"business\"> 业务归档</label>\n"
    "    </div>\n"
    "    <div class=\"log-export-actions\">\n"
    "      <button type=\"button\" class=\"btn\" id=\"log-all-types\">全部类型</button>\n"
    "      <button type=\"button\" class=\"btn\" id=\"log-refresh\">刷新列表</button>\n"
    "      <button type=\"button\" class=\"btn\" id=\"log-export-btn\" disabled>导出所选日志</button>\n"
    "      <a class=\"btn hidden\" id=\"log-package-download\">下载压缩包</a>\n"
    "    </div>\n"
    "    <p id=\"log-selection-summary\">正在读取日志列表…</p>\n"
    "    <div id=\"log-export-message\" role=\"status\" aria-live=\"polite\"></div>\n"
    "    <div class=\"log-export-table-wrap\" style=\"max-height:360px;overflow:auto;margin-top:12px\">\n"
    "      <table class=\"log-export-table\">\n"
    "        <thead><tr><th class=\"log-export-checkbox-cell\"><input type=\"checkbox\" id=\"log-select-all\" aria-label=\"选择全部文件\"></th><th>类型</th><th>文件名</th><th>大小</th><th>修改时间</th></tr></thead>\n"
    "        <tbody id=\"log-export-table-body\"></tbody>\n"
    "      </table>\n"
    "    </div>\n"
    "    <p style=\"font-size:13px;color:#667085;margin-top:12px\">每次最多512个文件、128MiB。系统启动日志在导出时采集；缺失或变化的文件会记录在包内清单中。</p>\n"
    "  </div>\n"
    "</div>\n"
    "<script>\n"
    "(function () {\n"
    "  var files = [], busy = false, requestNumber = 0, timer = null, alive = true;\n"
    "  var names = {web:'Web服务',mqtt:'MQTT通信',tk8710:'TK8710网关',daemon:'守护进程',system:'系统日志',upgrade:'升级日志',business:'业务归档'};\n"
    "  function node(id) { return document.getElementById(id); }\n"
    "  function types() { return Array.from(document.querySelectorAll('#log-types input:checked')).map(function(x){return x.value;}); }\n"
    "  function selected() { return Array.from(document.querySelectorAll('.log-file-choice:checked')).map(function(x){return files[Number(x.value)];}); }\n"
    "  function size(n) { return n < 1024 ? n+' B' : n < 1048576 ? (n/1024).toFixed(1)+' KiB' : (n/1048576).toFixed(1)+' MiB'; }\n"
    "  function message(text, error) { node('log-export-message').textContent=text;node('log-export-message').style.color=error?'#b42318':'#345b83'; }\n"
    "  function updateSelection() {\n"
    "    var entries=selected(), total=entries.reduce(function(n,f){return n+f.size;},0);\n"
    "    node('log-selection-summary').textContent='已选 '+entries.length+' 个文件，现有文件合计 '+size(total);\n"
    "    node('log-export-btn').disabled=busy || entries.length===0;\n"
    "    node('log-select-all').checked=files.length>0 && entries.length===files.length;\n"
    "    node('log-select-all').indeterminate=entries.length>0 && entries.length<files.length;\n"
    "  }\n"
    "  function setBusy(value) {\n"
    "    busy=value;\n"
    "    document.querySelectorAll('#log-types input, .log-file-choice, #log-select-all, #log-all-types, #log-refresh').forEach(function(x){x.disabled=value;});\n"
    "    updateSelection();\n"
    "  }\n"
    "  function render(list) {\n"
    "    files=list;var body=node('log-export-table-body');body.textContent='';\n"
    "    list.forEach(function(f,i) {\n"
    "      var tr=document.createElement('tr'), td=document.createElement('td'), input=document.createElement('input');\n"
    "      input.type='checkbox';input.className='log-file-choice';input.value=i;input.checked=true;input.disabled=busy;input.onchange=updateSelection;\n"
    "      td.className='log-export-checkbox-cell';td.appendChild(input);tr.appendChild(td);\n"
    "      [names[f.type]||f.type,f.name,f.id==='system/dmesg.txt'?'导出时采集':size(f.size),f.mtime].forEach(function(text){var cell=document.createElement('td');cell.textContent=text;tr.appendChild(cell);});\n"
    "      body.appendChild(tr);\n"
    "    });updateSelection();\n"
    "  }\n"
    "  function jsonFetch(url,options) {\n"
    "    return fetch(url,options).then(function(r) {\n"
    "      if(r.redirected)throw new Error('登录已失效，请重新登录');\n"
    "      return r.json().then(function(j){if(!r.ok)throw new Error(j.message||('HTTP '+r.status));return j;});\n"
    "    });\n"
    "  }\n"
    "  function load() {\n"
    "    if(busy)return;var chosen=types(),seq=++requestNumber;\n"
    "    if(!chosen.length){render([]);message('请选择日志类型。');return;}\n"
    "    message('正在读取日志列表…');node('log-export-btn').disabled=true;\n"
    "    jsonFetch('/api/logs?types='+encodeURIComponent(chosen.join(',')),{cache:'no-store'}).then(function(j) {\n"
    "      if(!alive || seq!==requestNumber)return;\n"
    "      render(j.files||[]);\n"
    "      var empty=(j.categories||[]).filter(function(c){return c.count===0;}).map(function(c){return c.label;});\n"
    "      message((j.truncated?'文件超过512个，列表仅展示部分，请缩小类型范围。 ':'')+(empty.length?'暂无日志：'+empty.join('、'):'已加载日志，可调整文件选择后导出。'));\n"
    "    }).catch(function(e){if(alive && seq===requestNumber){render([]);message(e.message,true);}});\n"
    "  }\n"
    "  function poll(id) {\n"
    "    jsonFetch('/api/log_export/status?id='+encodeURIComponent(id),{cache:'no-store'}).then(function(j) {\n"
    "      if(!alive)return;\n"
    "      if(j.status==='working') {\n"
    "        message(j.completed<j.total?'正在准备日志 '+j.completed+'/'+j.total+'…':'正在压缩日志，请稍候…');\n"
    "        timer=setTimeout(function(){poll(id);},1000);\n"
    "      } else {\n"
    "        setBusy(false);sessionStorage.removeItem('gateway-log-export');\n"
    "        if(j.status==='ready') {\n"
    "          var link=node('log-package-download');link.href='/api/log_export/download?id='+encodeURIComponent(id);link.classList.remove('hidden');\n"
    "          message('打包完成：'+j.exported+' 个文件'+(j.skipped?'，'+j.skipped+' 个文件无法读取，详情见manifest.json':'')+'。请点击“下载压缩包”。');\n"
    "        } else message(j.message||'导出失败，请重试。',true);\n"
    "      }\n"
    "    }).catch(function(e){if(alive){setBusy(false);sessionStorage.removeItem('gateway-log-export');message(e.message+'；刷新页面可重新检查任务。',true);}});\n"
    "  }\n"
    "  node('log-export-btn').onclick=function() {\n"
    "    var ids=selected().map(function(f){return f.id;});if(!ids.length||busy)return;\n"
    "    setBusy(true);node('log-package-download').classList.add('hidden');message('正在创建导出任务…');\n"
    "    jsonFetch('/api/log_export/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({types:types().join(','),files:ids})}).then(function(j){sessionStorage.setItem('gateway-log-export',j.id);poll(j.id);}).catch(function(e){setBusy(false);message(e.message,true);});\n"
    "  };\n"
    "  node('log-select-all').onchange=function(){var checked=this.checked;document.querySelectorAll('.log-file-choice').forEach(function(x){x.checked=checked;});updateSelection();};\n"
    "  node('log-all-types').onclick=function(){document.querySelectorAll('#log-types input').forEach(function(x){x.checked=true;});load();};\n"
    "  node('log-refresh').onclick=load;\n"
    "  document.querySelectorAll('#log-types input').forEach(function(x){x.onchange=load;});\n"
    "  window.addEventListener('pagehide',function(){alive=false;if(timer)clearTimeout(timer);});\n"
    "  load();var active=sessionStorage.getItem('gateway-log-export');if(active){setBusy(true);poll(active);}\n"
    "})();\n"
    "</script>\n"
    "";

static const char *RES_HTML_UPGRADE_MAINTENANCE_HTML = 
    "<div class=\"panel\"><div class=\"panel-header\">设备维护</div><div class=\"panel-body\"><form method=\"post\" action=\"/upgrade\" onsubmit=\"return confirm('确定要重启设备吗？');\"><input type=\"hidden\" name=\"action\" value=\"reboot\"><div class=\"form-group\"><label class=\"form-label\">操作</label><button type=\"submit\" class=\"btn\" style=\"background-color:#d9534f;border-color:#d43f3a;\">重启设备</button></div></form></div></div>";

#endif // WEB_RESOURCES_H
